import moment from 'moment-timezone';

moment.tz.add('Factory|0|0|0||');
class MomentDateEngine {
    get name() {
        return 'moment';
    }
    create(date) {
        return moment(date);
    }
    increase(date) {
        return date.add(1, 'days');
    }
    formatToIsoDateString(date) {
        return date.format('YYYY-MM-DD');
    }
    isoToTimeZone(isoDate, tz) {
        return moment.tz(isoDate, tz);
    }
    same(date1, date2) {
        return date1.isSame(date2);
    }
}

export { MomentDateEngine as DateEngine };
